package com.sports.payment_service.client; import com.fasterxml.jackson.databind.*; import com.sports.payment_service.exception.ExternalServiceException; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestTemplate; import java.util.*; @Component public class PaystackClient { private final RestTemplate rt=new RestTemplate(); private final ObjectMapper om=new ObjectMapper(); @Value("${paystack.secret-key:}") String key; @Value("${paystack.base-url:https://api.paystack.co}") String base; public JsonNode initialize(String email,Long amount,String ref,String cb){ensure(); Map<String,Object>b=new HashMap<>(); b.put("email",email); b.put("amount",String.valueOf(amount)); b.put("reference",ref); if(cb!=null&&!cb.isBlank())b.put("callback_url",cb); return x(base+"/transaction/initialize",HttpMethod.POST,new HttpEntity<>(b,h()));} public JsonNode verify(String ref){ensure(); return x(base+"/transaction/verify/"+ref,HttpMethod.GET,new HttpEntity<>(h()));} private JsonNode x(String u,HttpMethod m,HttpEntity<?> e){try{var r=rt.exchange(u,m,e,String.class); if(!r.getStatusCode().is2xxSuccessful()||r.getBody()==null)throw new ExternalServiceException("Paystack returned an unsuccessful response"); return om.readTree(r.getBody());}catch(Exception ex){if(ex instanceof ExternalServiceException ee)throw ee; throw new ExternalServiceException("Could not reach/read Paystack",ex);}} private HttpHeaders h(){var h=new HttpHeaders(); h.setBearerAuth(key); h.setContentType(MediaType.APPLICATION_JSON); return h;} private void ensure(){if(key==null||key.isBlank())throw new ExternalServiceException("PAYSTACK_SECRET_KEY is not configured");}}